import { useEffect, useState, useCallback, useMemo } from "react";
import { UserPlus, Pencil, Trash2, X, ShieldCheck, AlertTriangle, Search, ChevronDown, ChevronRight } from "lucide-react";
import { apiGet, apiPost, apiPatch, apiDelete, getUser, updateSession } from "../../lib/api.js";
import { PERMISSIONS, DEFAULT_PERMISSIONS } from "../../../../permissions.js";
import { useLang } from "../../lib/i18n.jsx";

/**
 * Account control (requires the "manage accounts" permission).
 *
 * Create / edit / delete accounts, each with an explicit set of permissions
 * (tickboxes). The list of permissions comes from the shared permissions.js at
 * the project root — add one entry there and the checkbox + chip appear here
 * automatically. The backend enforces every permission.
 */

const EMPTY_FORM = {
  username: "",
  name: "",
  password: "",
  role: "staff",
  perms: { ...DEFAULT_PERMISSIONS, manageDelegates: true },
};

// Exactly two roles — role is now an independent field, submitted as-is
// alongside the permission checkboxes (see backend/data.js's createAccount/
// updateAccount). Picking "Admin" here pre-fills every checkbox ticked as a
// preview, but it's cosmetic: an Admin account bypasses every permission
// check regardless of what's stored (accountPermissions() in data.js always
// returns all-true for role="admin"), so the checkboxes are hidden entirely
// once Admin is selected — see the form below. Staff's checkboxes are the
// real, enforced access grant, defaulting to EMPTY_FORM's perms (each
// permission's own `default` from permissions.js — action permissions
// mostly closed, view permissions open; see that file's group doc).
// Derived from PERMISSIONS rather than hardcoded so a new permission entry
// there is automatically included here too — nothing to update by hand.
const ROLE_PRESETS = {
  staff: DEFAULT_PERMISSIONS,
  admin: Object.fromEntries(PERMISSIONS.map((p) => [p.key, true])),
};

// The three labelled, collapsible sections the modal's checkboxes are
// grouped into — order matches how an admin thinks about it: what can this
// account DO, then what can it SEE on desktop, then what can it SEE on
// mobile. `selectAll: true` adds a "Select all / Deselect all" toggle to
// that section's header — only the two view groups get one (the request
// that added this was specifically "select all for desktop and mobile");
// Feature actions is short enough, and typically NOT all-or-nothing per
// account, to not need one.
const PERM_GROUPS = [
  { key: "action", title: "Feature actions", desc: "What this account can create, edit or delete" },
  { key: "desktopView", title: "Desktop web views", desc: "Which pages this account can see on the desktop dashboard", selectAll: true },
  { key: "mobileView", title: "Mobile views", desc: "Which tabs this account can see in the mobile app", selectAll: true },
];

const ERR_TEXT = {
  USERNAME_TAKEN: "That username is already taken.",
  USERNAME_REQUIRED: "Username is required.",
  PASSWORD_REQUIRED: "Password is required.",
  WEAK_PASSWORD: "Password must be at least 8 characters, with a letter and a number.",
  LAST_MAIN: "You can't remove or demote the last Admin account.",
  NOT_FOUND: "That account no longer exists.",
};

// Password rule (mirrors the backend check in data.js). Returns a message, or
// null if the password is acceptable.
const PW_HINT = "At least 8 characters, including a letter and a number.";
function passwordProblem(pw) {
  const s = String(pw || "");
  if (s.length < 8) return "Password must be at least 8 characters.";
  if (!/[A-Za-z]/.test(s)) return "Password must include at least one letter.";
  if (!/[0-9]/.test(s)) return "Password must include at least one number.";
  return null;
}

export default function AccountControlPage() {
  const { t, lang } = useLang();
  const [accounts, setAccounts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const [modalOpen, setModalOpen] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(EMPTY_FORM);
  const [formErr, setFormErr] = useState("");
  const [saving, setSaving] = useState(false);
  // Which PERM_GROUPS sections are collapsed in the New/Edit modal — a Set
  // of group keys, so state persists across re-renders but resets (all
  // expanded) every time the modal is freshly opened, see openCreate/
  // openEdit below.
  const [collapsedGroups, setCollapsedGroups] = useState(new Set());

  // Search / filter / sort for the accounts table.
  const [search, setSearch] = useState("");
  const [roleFilter, setRoleFilter] = useState("ALL"); // ALL | admin | staff
  const [sortMode, setSortMode] = useState("username"); // username | name | role

  // Batch selection — Set of account ids. Your OWN account is never
  // selectable (see visibleAccounts below and the row checkbox), so a batch
  // delete can't lock you out of your own session mid-loop.
  const [selectedIds, setSelectedIds] = useState(new Set());
  const [deletingSelected, setDeletingSelected] = useState(false);

  const me = getUser() || {};

  const load = useCallback(async () => {
    setLoading(true);
    setError("");
    try {
      const data = await apiGet("/accounts");
      setAccounts(data.accounts || []);
    } catch (e) {
      setError(e.message || "Could not load accounts.");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  // Search + role filter + sort, applied in that order. Search matches
  // username or display name (case-insensitive substring).
  const visibleAccounts = useMemo(() => {
    const q = search.trim().toLowerCase();
    let list = accounts.filter((a) => {
      const role = a.role === "admin" ? "admin" : "staff";
      if (roleFilter !== "ALL" && role !== roleFilter) return false;
      if (q) {
        const hay = `${a.username || ""} ${a.name || ""}`.toLowerCase();
        if (!hay.includes(q)) return false;
      }
      return true;
    });
    const byUsername = (a, b) => (a.username || "").localeCompare(b.username || "");
    list = [...list].sort((a, b) => {
      if (sortMode === "name") return (a.name || "").localeCompare(b.name || "") || byUsername(a, b);
      if (sortMode === "role") return (a.role || "").localeCompare(b.role || "") || byUsername(a, b);
      return byUsername(a, b); // username
    });
    return list;
  }, [accounts, search, roleFilter, sortMode]);

  // Every visible account EXCEPT your own — your own account is never
  // selectable for batch delete (see the row checkbox below).
  const selectableVisible = useMemo(() => visibleAccounts.filter((a) => a.username !== me.username), [visibleAccounts, me.username]);
  const allSelectableChecked = selectableVisible.length > 0 && selectableVisible.every((a) => selectedIds.has(a.id));

  function toggleSelected(id) {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  }

  function toggleSelectAll() {
    setSelectedIds((prev) => {
      if (allSelectableChecked) return new Set();
      return new Set(selectableVisible.map((a) => a.id));
    });
  }

  async function deleteSelected() {
    const count = selectedIds.size;
    if (count === 0) return;
    const msg = lang === "zh"
      ? `确定删除选中的 ${count} 个账户？此操作无法撤销。`
      : `Delete ${count} selected account${count === 1 ? "" : "s"}? This cannot be undone.`;
    if (!window.confirm(msg)) return;

    setDeletingSelected(true);
    setError("");
    const ids = [...selectedIds];
    const results = await Promise.allSettled(ids.map((id) => apiDelete(`/accounts/${id}`)));
    const failed = results.filter((r) => r.status === "rejected");
    if (failed.length > 0) {
      // Most likely cause: the "last admin" guard blocked one of them —
      // show the first failure's message rather than a generic one.
      setError(mapError(failed[0].reason, "LAST_MAIN"));
    }
    setSelectedIds(new Set());
    setDeletingSelected(false);
    await load();
  }

  // Deletes every account EXCEPT your own (never itself deletable — same
  // rule as the row checkboxes). The backend's "last admin" guard still
  // blocks removing the only remaining admin, so at minimum your own account
  // survives this.
  async function deleteAllAccounts() {
    const targets = accounts.filter((a) => a.username !== me.username);
    if (targets.length === 0) return;
    const msg = lang === "zh"
      ? `确定删除除您以外的全部 ${targets.length} 个账户？此操作无法撤销。`
      : `Delete ALL ${targets.length} other account${targets.length === 1 ? "" : "s"} (everyone except you)? This cannot be undone.`;
    if (!window.confirm(msg)) return;

    setDeletingSelected(true);
    setError("");
    const results = await Promise.allSettled(targets.map((a) => apiDelete(`/accounts/${a.id}`)));
    const failed = results.filter((r) => r.status === "rejected");
    if (failed.length > 0) {
      setError(mapError(failed[0].reason, "LAST_MAIN"));
    }
    setSelectedIds(new Set());
    setDeletingSelected(false);
    await load();
  }

  function openCreate() {
    setEditingId(null);
    setForm({ ...EMPTY_FORM, perms: { ...EMPTY_FORM.perms } });
    setFormErr("");
    setCollapsedGroups(new Set(PERM_GROUPS.map((g) => g.key)));
    setModalOpen(true);
  }

  function openEdit(a) {
    setEditingId(a.id);
    const perms = Object.fromEntries(PERMISSIONS.map((p) => [p.key, !!a.permissions?.[p.key]]));
    setForm({
      username: a.username,
      name: a.name || "",
      password: "",
      perms,
      role: a.role === "admin" ? "admin" : "staff",
    });
    setFormErr("");
    setCollapsedGroups(new Set(PERM_GROUPS.map((g) => g.key)));
    setModalOpen(true);
  }

  function togglePerm(key) {
    setForm((f) => ({ ...f, perms: { ...f.perms, [key]: !f.perms[key] } }));
  }

  function selectRole(role) {
    setForm((f) => ({ ...f, role, perms: { ...f.perms, ...ROLE_PRESETS[role] } }));
  }

  function toggleGroupCollapsed(groupKey) {
    setCollapsedGroups((prev) => {
      const next = new Set(prev);
      if (next.has(groupKey)) next.delete(groupKey); else next.add(groupKey);
      return next;
    });
  }

  // "Select all" toggles to "Deselect all" once every checkbox in the group
  // is already ticked — same on/off convention as the accounts table's own
  // header "select all" checkbox.
  function setAllInGroup(groupKey, value) {
    setForm((f) => {
      const perms = { ...f.perms };
      for (const p of PERMISSIONS) if (p.group === groupKey) perms[p.key] = value;
      return { ...f, perms };
    });
  }

  function mapError(e, fallbackCode) {
    // Prefer the backend's error code (now carried on the Error), then fall back
    // to matching the message text or a 409 conflict.
    const code =
      (e.code && ERR_TEXT[e.code] ? e.code : "") ||
      Object.keys(ERR_TEXT).find((k) => String(e.message).includes(k)) ||
      (e.status === 409 || String(e.message).includes("409") ? fallbackCode : "");
    // For weak passwords the backend sends a specific message — show it verbatim.
    if (e.code === "WEAK_PASSWORD" && e.message) return e.message;
    return ERR_TEXT[code] || "Something went wrong. Please try again.";
  }

  async function save() {
    setFormErr("");
    if (!form.username.trim()) return setFormErr(ERR_TEXT.USERNAME_REQUIRED);
    if (!editingId && !form.password) return setFormErr(ERR_TEXT.PASSWORD_REQUIRED);
    // Enforce the password rule when creating, or when editing AND a new
    // password was typed (blank on edit = keep the current one).
    if (form.password) {
      const pw = passwordProblem(form.password);
      if (pw) return setFormErr(pw);
    }

    setSaving(true);
    const payload = {
      username: form.username.trim(),
      name: form.name.trim(),
      role: form.role,
      permissions: form.perms,
    };
    if (form.password) payload.password = form.password; // blank on edit = keep current

    try {
      if (editingId) {
        const resp = await apiPatch(`/accounts/${editingId}`, payload);
        // If you edited your OWN account, refresh the saved session (new token +
        // name/permissions) and reload so everything (including the sidebar and
        // the auth token) reflects the change without a re-login.
        if (resp?.self) {
          updateSession({
            token: resp.token,
            user: {
              username: resp.account.username,
              staffId: resp.account.username,
              name: resp.account.name,
              role: resp.account.role,
              permissions: resp.account.permissions,
            },
          });
          window.location.reload();
          return;
        }
      } else {
        await apiPost("/accounts", payload);
      }
      setModalOpen(false);
      await load();
    } catch (e) {
      setFormErr(mapError(e, "USERNAME_TAKEN"));
    } finally {
      setSaving(false);
    }
  }

  async function remove(a) {
    const msg = lang === "zh"
      ? `确定删除账户 "${a.username}"？此操作无法撤销。`
      : `Delete account "${a.username}"? This cannot be undone.`;
    if (!window.confirm(msg)) return;
    setError("");
    try {
      await apiDelete(`/accounts/${a.id}`);
      await load();
    } catch (e) {
      setError(mapError(e, "LAST_MAIN"));
    }
  }

  return (
    <div className="page">
      <div className="row between" style={{ alignItems: "flex-start", flexWrap: "wrap", gap: 16 }}>
        <div>
          <div className="page-eyebrow">{t("Administration")}</div>
          <h1 className="page-title">{t("Account control")}</h1>
          <p className="page-sub">{t("Create accounts and choose exactly what each one can do.")}</p>
        </div>
        <div className="row" style={{ gap: 10 }}>
          {selectedIds.size > 0 && (
            <button
              className="btn btn-ghost"
              style={{ color: "var(--st-missing)", borderColor: "var(--st-missing-bg)" }}
              onClick={deleteSelected}
              disabled={deletingSelected}
            >
              <Trash2 size={16} /> {deletingSelected ? t("Deleting…") : `${t("Delete selected")} (${selectedIds.size})`}
            </button>
          )}
          {accounts.length > 1 && (
            <button
              className="btn btn-ghost"
              style={{ color: "var(--st-missing)", borderColor: "var(--st-missing-bg)" }}
              onClick={deleteAllAccounts}
              disabled={deletingSelected}
            >
              <Trash2 size={16} /> {t("Delete all")}
            </button>
          )}
          <button className="btn btn-primary" onClick={openCreate}>
            <UserPlus size={16} /> {t("New account")}
          </button>
        </div>
      </div>

      {error && (
        <div className="card" style={{ marginTop: 20, padding: 14, borderColor: "var(--st-missing)", background: "var(--st-missing-bg)" }}>
          <div className="row" style={{ gap: 8, color: "var(--st-missing)", fontWeight: 600, fontSize: 14 }}>
            <AlertTriangle size={16} /> {t(error)}
          </div>
        </div>
      )}

      <div className="card" style={{ marginTop: 20, overflow: "hidden" }}>
        <div className="row" style={{ padding: "16px 20px", borderBottom: "1px solid var(--line)", gap: 8 }}>
          <ShieldCheck size={18} color="var(--ink-3)" />
          <h2 style={{ fontSize: 16 }}>{t("Accounts")}</h2>
          <span className="muted" style={{ fontSize: 13, marginLeft: "auto" }}>{accounts.length} {t("total")}</span>
        </div>

        {accounts.length > 0 && (
          <div className="row" style={{ gap: 10, padding: "12px 20px", borderBottom: "1px solid var(--line)", flexWrap: "wrap" }}>
            <div style={{ position: "relative", maxWidth: 240, flex: "1 1 180px" }}>
              <Search size={15} style={{ position: "absolute", left: 10, top: "50%", transform: "translateY(-50%)", color: "var(--ink-3)" }} />
              <input
                className="input"
                style={{ paddingLeft: 32 }}
                placeholder={t("Search accounts…")}
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </div>
            <select className="select" style={{ maxWidth: 160 }} value={roleFilter} onChange={(e) => setRoleFilter(e.target.value)}>
              <option value="ALL">{t("All roles")}</option>
              <option value="admin">{t("Admin")}</option>
              <option value="staff">{t("Staff")}</option>
            </select>
            <select className="select" style={{ maxWidth: 190 }} value={sortMode} onChange={(e) => setSortMode(e.target.value)}>
              <option value="username">{t("Sort: Username")}</option>
              <option value="name">{t("Sort: Name")}</option>
              <option value="role">{t("Sort: Role")}</option>
            </select>
          </div>
        )}

        {loading ? (
          <div className="muted" style={{ padding: 24, fontSize: 14 }}>{t("Loading…")}</div>
        ) : accounts.length === 0 ? (
          <div className="muted" style={{ padding: 24, fontSize: 14 }}>{t("No accounts yet.")}</div>
        ) : (
          <table className="table">
            <thead>
              <tr>
                <th style={{ width: 36 }}>
                  <input
                    type="checkbox"
                    checked={allSelectableChecked}
                    onChange={toggleSelectAll}
                    disabled={selectableVisible.length === 0}
                    aria-label={t("Select all")}
                  />
                </th>
                <th>{t("Username")}</th><th>{t("Name")}</th><th>{t("Role")}</th><th>{t("Access")}</th><th style={{ width: 90 }} />
              </tr>
            </thead>
            <tbody>
              {visibleAccounts.length === 0 && (
                <tr>
                  <td colSpan={6} className="muted" style={{ padding: 24, fontSize: 14, textAlign: "center" }}>
                    {t("No accounts match your filters.")}
                  </td>
                </tr>
              )}
              {visibleAccounts.map((a) => {
                const isMe = a.username === me.username;
                const isAdmin = a.role === "admin";
                // Table chips show only ACTION permissions — view permissions
                // default to open for everyone (see permissions.js), so
                // listing all of them here would be 8+ near-identical chips
                // on almost every row. The modal is where per-page view
                // access actually gets configured/audited.
                const granted = PERMISSIONS.filter((p) => p.group === "action" && a.permissions?.[p.key]);
                return (
                  <tr key={a.id}>
                    <td>
                      <input
                        type="checkbox"
                        checked={selectedIds.has(a.id)}
                        onChange={() => toggleSelected(a.id)}
                        disabled={isMe}
                        title={isMe ? t("You can't select your own account for batch delete.") : undefined}
                        aria-label={`${t("Select")} ${a.username}`}
                      />
                    </td>
                    <td>
                      <div className="row" style={{ gap: 10 }}>
                        <span className="avatar" style={{ background: "var(--st-neutral-bg)", color: "var(--ink-2)" }}>
                          {a.username.slice(0, 2).toUpperCase()}
                        </span>
                        <span className="mono" style={{ fontWeight: 500 }}>{a.username}</span>
                        {isMe && <span className="badge badge-present" style={{ padding: "2px 8px" }}>{t("You")}</span>}
                      </div>
                    </td>
                    <td>{a.name || "—"}</td>
                    <td>
                      <span className={"badge " + (isAdmin ? "badge-missing" : "badge-neutral")} style={{ padding: "2px 8px" }}>
                        {isAdmin ? t("Admin") : t("Staff")}
                      </span>
                    </td>
                    <td>
                      <div className="row" style={{ gap: 6, flexWrap: "wrap" }}>
                        {granted.length === 0 ? (
                          <span className="badge badge-neutral">{t("View only")}</span>
                        ) : (
                          granted.map((p) => (
                            <span
                              key={p.key}
                              className={"badge " + (p.key === "manageAccounts" ? "badge-missing" : "badge-normal")}
                              style={{ padding: "2px 8px" }}
                            >
                              {p.chip}
                            </span>
                          ))
                        )}
                      </div>
                    </td>
                    <td>
                      <div className="row" style={{ gap: 6 }}>
                        <button onClick={() => openEdit(a)} aria-label={`${t("Edit")} ${a.username}`} style={S.iconBtn}>
                          <Pencil size={16} />
                        </button>
                        <button onClick={() => remove(a)} aria-label={`${t("Delete")} ${a.username}`} style={{ ...S.iconBtn, color: "var(--st-missing)" }}>
                          <Trash2 size={16} />
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>

      {/* Create / edit modal */}
      {modalOpen && (
        <div style={S.overlay} onClick={() => !saving && setModalOpen(false)}>
          <div className="card" style={S.modal} onClick={(e) => e.stopPropagation()}>
            <div className="row between" style={{ marginBottom: 18 }}>
              <h2 style={{ fontSize: 18 }}>{editingId ? t("Edit account") : t("New account")}</h2>
              <button onClick={() => setModalOpen(false)} style={S.iconBtn} aria-label={t("Close")}><X size={18} /></button>
            </div>

            <label className="field-label">{t("Username")}</label>
            <input className="input mono" autoFocus value={form.username}
              placeholder={t("e.g. staff_123")}
              onChange={(e) => setForm({ ...form, username: e.target.value })} />

            <label className="field-label" style={{ marginTop: 14 }}>{t("Name")} <span className="muted">({t("display only")})</span></label>
            <input className="input" value={form.name}
              placeholder={t("e.g. John Tan")}
              onChange={(e) => setForm({ ...form, name: e.target.value })} />

            <label className="field-label" style={{ marginTop: 14 }}>
              {t("Password")} {editingId && <span className="muted">({t("leave blank to keep current")})</span>}
            </label>
            <input className="input" type="password" value={form.password}
              placeholder={editingId ? "••••••••" : t("Set a password")}
              onChange={(e) => setForm({ ...form, password: e.target.value })} />
            {(!editingId || form.password) && (
              <p className="muted" style={{ fontSize: 12, marginTop: 6,
                color: form.password && passwordProblem(form.password) ? "var(--st-missing)" : undefined }}>
                {t(PW_HINT)}
              </p>
            )}

            <label className="field-label" style={{ marginTop: 18 }}>{t("Role")}</label>
            <div className="row" style={{ gap: 8 }}>
              {["staff", "admin"].map((r) => (
                <button
                  key={r}
                  type="button"
                  className={"btn " + (form.role === r ? "btn-primary" : "btn-ghost")}
                  style={{ flex: 1 }}
                  onClick={() => selectRole(r)}
                >
                  {t(r === "staff" ? "Staff" : "Admin")}
                </button>
              ))}
            </div>
            <p className="muted" style={{ fontSize: 12, marginTop: 6 }}>
              {form.role === "admin"
                ? t("Admins bypass every check below — full access to every tab and feature.")
                : t("Staff are limited to exactly what's ticked below.")}
            </p>

            {form.role === "staff" && (
              <>
                {PERM_GROUPS.map((g) => {
                  // adminOnly permissions (e.g. manageAccounts) never render as a
                  // Staff toggle — only a real Admin should ever grant/revoke
                  // everyone else's access (see permissions.js's adminOnly doc).
                  const allPerms = PERMISSIONS.filter((p) => p.group === g.key && !p.adminOnly);
                  if (allPerms.length === 0) return null;
                  // Top-level perms render in order; a perm with a `parent`
                  // renders indented immediately under that parent instead of
                  // in the main flow (see permissions.js's `parent` doc).
                  const topLevel = allPerms.filter((p) => !p.parent || !allPerms.some((pp) => pp.key === p.parent));
                  const childrenOf = (key) => allPerms.filter((p) => p.parent === key);
                  const collapsed = collapsedGroups.has(g.key);
                  const allChecked = allPerms.every((p) => !!form.perms[p.key]);
                  return (
                    <div key={g.key} style={{ marginTop: 18 }}>
                      <div className="row between" style={{ alignItems: "flex-start", gap: 8 }}>
                        <button
                          type="button"
                          onClick={() => toggleGroupCollapsed(g.key)}
                          aria-expanded={!collapsed}
                          style={{
                            background: "none", border: "none", padding: 0, cursor: "pointer",
                            display: "flex", alignItems: "flex-start", gap: 6, textAlign: "left", flex: 1,
                          }}
                        >
                          {collapsed ? <ChevronRight size={16} style={{ marginTop: 2, flexShrink: 0, color: "var(--ink-3)" }} />
                                     : <ChevronDown size={16} style={{ marginTop: 2, flexShrink: 0, color: "var(--ink-3)" }} />}
                          <span>
                            <span className="field-label" style={{ display: "block" }}>{t(g.title)}</span>
                            <span className="muted" style={{ fontSize: 12 }}>{t(g.desc)}</span>
                          </span>
                        </button>
                        {g.selectAll && (
                          <button
                            type="button"
                            className="btn btn-ghost"
                            style={{ fontSize: 12, padding: "5px 10px", flexShrink: 0 }}
                            onClick={() => setAllInGroup(g.key, !allChecked)}
                          >
                            {allChecked ? t("Deselect all") : t("Select all")}
                          </button>
                        )}
                      </div>
                      {!collapsed && (
                        <div style={{ display: "flex", flexDirection: "column", gap: 8, marginTop: 8 }}>
                          {topLevel.map((p) => (
                            <PermRow
                              key={p.key}
                              perm={p}
                              form={form}
                              togglePerm={togglePerm}
                              childrenOf={childrenOf}
                              t={t}
                            />
                          ))}
                        </div>
                      )}
                    </div>
                  );
                })}
              </>
            )}

            {formErr && (
              <div style={S.formErr}><AlertTriangle size={15} /> {t(formErr)}</div>
            )}

            <div className="row" style={{ gap: 10, marginTop: 22, justifyContent: "flex-end" }}>
              <button className="btn btn-ghost" onClick={() => setModalOpen(false)} disabled={saving}>{t("Cancel")}</button>
              <button className="btn btn-primary" onClick={save} disabled={saving}>
                {saving ? t("Saving…") : editingId ? t("Save changes") : t("Create account")}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// Renders one permission checkbox, then recurses into its children indented
// underneath — supports any nesting depth (currently 2 levels are used:
// dashboard -> Delegate -> History logs), not just direct parent/child.
function PermRow({ perm, form, togglePerm, childrenOf, t }) {
  const kids = childrenOf(perm.key);
  return (
    <div>
      <label style={S.permRow}>
        <input
          type="checkbox"
          checked={!!form.perms[perm.key]}
          onChange={() => togglePerm(perm.key)}
          style={{ marginTop: 3 }}
        />
        <span>
          <span style={{ fontWeight: 600, fontSize: 14 }}>{t(perm.label)}</span>
          <span className="muted" style={{ display: "block", fontSize: 12 }}>{t(perm.desc)}</span>
        </span>
      </label>
      {kids.length > 0 && (
        <div style={{ display: "flex", flexDirection: "column", gap: 8, marginTop: 8, marginLeft: 26, borderLeft: "2px solid var(--line)", paddingLeft: 12 }}>
          {kids.map((cp) => (
            <PermRow key={cp.key} perm={cp} form={form} togglePerm={togglePerm} childrenOf={childrenOf} t={t} />
          ))}
        </div>
      )}
    </div>
  );
}

const S = {
  iconBtn: { background: "none", border: "none", color: "var(--ink-3)", display: "flex", padding: 4, borderRadius: 6 },
  overlay: { position: "fixed", inset: 0, background: "rgba(16,24,40,0.45)", display: "grid", placeItems: "center", padding: 20, zIndex: 50 },
  modal: { width: "min(460px, 100%)", padding: 24, background: "var(--surface)", maxHeight: "90vh", overflowY: "auto" },
  permRow: {
    display: "flex", alignItems: "flex-start", gap: 10, cursor: "pointer",
    padding: "10px 12px", border: "1px solid var(--line)", borderRadius: "var(--r-sm)",
  },
  formErr: {
    display: "flex", alignItems: "center", gap: 8, marginTop: 16, padding: "10px 12px",
    background: "var(--st-missing-bg)", color: "var(--st-missing)", borderRadius: "var(--r-sm)",
    fontSize: 13, fontWeight: 600,
  },
};
